import numpy as np

def se2(x, y, th):
    c, s = np.cos(th), np.sin(th)
    return np.array([[c, -s, x], [s, c, y], [0, 0, 1.0]])

def edge_error(xi, xj, z):
    """Error of a pose-graph edge. xi, xj: current estimates (x, y, theta) of poses i and j in the world.
    z: the measured pose of j in i's frame, (x, y, theta). Return vec(Z^-1 Xi^-1 Xj) as (x, y, theta),
    with theta in (-pi, pi]. It is zero when the estimates agree exactly with the measurement."""
    return np.array(xj, dtype=float) - np.array(xi, dtype=float) - np.array(z, dtype=float)

